  ('hedschebedsch', 'Hedschebedsch', '', '', '', '', 'Hetschepetsch', '[{"kategorie": "", "text": "Hagebutte"}, {"kategorie": "", "text": "rote bis orangefarbene Frucht der Heckenrose (\"Rosa canina\")"}]'::jsonb, ''),
  ('hetzich', 'hetzich', '', '', '', '', 'hetzig', '[{"kategorie": "", "text": "flott, schnell wendig"}, {"kategorie": "", "text": "spaßig, lustig"}, {"kategorie": "", "text": "ulkig, komisch"}]'::jsonb, ''),
  ('hei', 'Hei', '', '', '', '', 'Hei', '[{"kategorie": "", "text": "Heu (wörtlich: \"das gehauene Gras\")"}, {"kategorie": "", "text": "Heubett, Bett aus Heu"}, {"kategorie": "", "text": "Tabak, Schnupftabak"}, {"kategorie": "", "text": "Geld, Bargeld"}]'::jsonb, ''),
