  ('heigeign', 'Heigeign', '', '', '', '', 'Heugeige', '[{"kategorie": "wörtlich", "text": "lange Stange, mit der das Heu auf dem heuwagen fixiert wird"}, {"kategorie": "", "text": "dünne, große Person"}, {"kategorie": "", "text": "lange, dürre Frau"}]'::jsonb, ''),
  ('heigeigngschdoeoe', 'Heigeigngschdöö', '', '', '', '', 'Heugeigengestell', '[{"kategorie": "wörtlich", "text": "Holzgestell zum Grastrocknen"}, {"kategorie": "", "text": "\"Klappergestell\", \"wandelndes Gerippe\", Knochengerüst, [[Schääwada]], [[Skelettgigerl]]  (nur aus Haut und Knochen bestehender Mensch)"}, {"kategorie": "", "text": "[[Krischpindl]] (abgemagerter, knochendürrer Mensch)"}]'::jsonb, 'Du oids, schääwads Heigeigngschdöö!'),
  ('zwianblaada', 'Zwianblaada', '', '', '', '', 'Zwirnblader', '[{"kategorie": "", "text": "dürrer, hagerer Mensch (der so dünn ist wie ein Zwirn)"}, {"kategorie": "", "text": "[[dirre]] Graadn, [[Schmoipickda]]"}]'::jsonb, ''),
  ('heimoakd', 'Heimoakd', '', '', '', '', 'Heumarkt', '[{"kategorie": "", "text": "\"Am Heumarkt\" (Name einer der ältesten Straßen Wiens, welche sich im 3. Wiener Gemeindebezirk [[[Landstraße]]] befindet)"}, {"kategorie": "", "text": "Der Name \"Heumarkt\" geht auf die Zeit zurück, als der Platz als Marktplatz für den Handel mit Heu und anderen landwirtschaftlichen Produkten diente. Diese Funktion prägte den Platz während des 18. und 19. Jahrhunderts. Der Heumarkt war im Laufe der Zeit auch Schauplatz für verschiedene städtische Veranstaltungen und wurde gelegentlich für Märkte und Messen genutzt"}, {"kategorie": "", "text": "Am Heumarkt befindet sich auch der Sitz des [[Wiener]] Eislaufvereins, der dort eine der größten Freiluft-Eisflächen Europas betreibt und dessen Areal bis 1997 auch als Kampfstätte der Freistilringer genutzt wurde"}]'::jsonb, ''),
  ('heimoakdschmaeae', 'Heimoakdschmää', '', '', '', '', 'Heumarktschmäh', '[{"kategorie": "wörtlich", "text": "höchst kreative und vor allem vulgäre Anfeuerungsrufe für die legendären \"Catcher\" (Freistilringer) am Heumarkt"}, {"kategorie": "symbolisch für", "text": "1. Prügelei"}, {"kategorie": "", "text": "\"Catcherei\" (in Anspielung auf das legendäre Kampfspektakel [[Catchen am Heumarkt]], dessen Freistilringkämpfe bis 1997 Am [[Heumarkt]] auf dem Areal des [[Wiener]] Eislaufvereins stattgefunden haben)"}]'::jsonb, ''),
  ('eislaufvarein', 'Eislaufvarein', '', '', '', '', 'Eislaufverein', '[{"kategorie": "wörtlich, Kurzform für:", "text": "\"Wiener Eiselaufverein\" (\"WEV\") - einer der ältesten und bekanntesten Eislaufvereine der Welt und ein bedeutendes Zentrum für den Eissport in Wien\""}, {"kategorie": "", "text": "Der Verein betreibt eine große Freiluft-Eisfläche im 3. Bezirk ([[Landstraße]]), nahe dem [[Stadtpark]] und der [[Wiener]] Ringstraße, und bietet eine Plattform für Eislaufsport, darunter Eiskunstlauf, Eishockey und Freizeiteislaufen"}, {"kategorie": "", "text": "Der Wiener Eislauf-Verein wurde am 7. Februar 1867 gegründet, zu einer Zeit, als das Eislaufen in Wien immer beliebter wurde. Die ersten Eisbahnen wurden auf zugefrorenen Gewässern wie dem Wiener Donaukanal eingerichtet.  1901 bezog der Verein seine heutige Anlage am Heumarkt im 3. Bezirk, die schnell zu einem Zentrum des Eissports in Wien wurde. Die Eisfläche des Vereins war die erste künstlich angelegte Freiluft-Eisbahn in der Stadt"}, {"kategorie": "", "text": "Auf dem Areal des WEV fanden bis 1997 auch die legendären \"Catcher- und Freistilringkämpfe\" statt"}]'::jsonb, ''),
  ('straussdenkmoi', 'Straussdenkmoi', '', '', '', '', 'Straußdenkmal', '[{"kategorie": "", "text": "Es wurde zu Ehren von [[Johann]] Strauß (Sohn) im [[Wiener]] Stadtpark errichtet und zeigt den \"vergoldeten\" Wiener Walzerkönig  vor einem weißen Marmorbogen mit Reliefs von schwebenden Paaren und Blättern"}, {"kategorie": "", "text": "Das Denkmal wurde 1921 eingeweiht, um Johann Strauss (Sohn) zu ehren, der für seine Walzerkompositionen wie \"An der schönen blauen Donau\" ([[Donauwalzer]]) und \"Kaiser-Walzer\" weltweit berühmt ist. Strauss gilt als einer der bedeutendsten Komponisten der Wiener Musikgeschichte. Die Errichtung des Denkmals wurde durch Spenden finanziert, und es war von Anfang an als eine der zentralen Attraktionen im Wiener Stadtpark gedacht"}, {"kategorie": "", "text": "Das Johann-Strauß-Denkmal zeigt eine lebensgroße Statue von Johann Strauss, der in typischer Pose mit einer Violine in den Händen dargestellt ist. Die Figur ist aus Bronze gefertigt und mit einer auffälligen Vergoldung versehen, die der Statue ihren ikonischen Glanz verleiht"}, {"kategorie": "", "text": "Das Denkmal wurde von dem Bildhauer Edmund Hellmer geschaffen, einem bedeutenden österreichischen Künstler, der für seine Arbeiten im Stil des [[Historismus]] bekannt war."}]'::jsonb, ''),
  ('stodtpark', 'Stodtpark', '', '', '', '', 'Stadtpark', '[{"kategorie": "hist.", "text": "\"einer der bekanntesten und ältesten öffentlichen Parks der Stadt mit einer Fläche von etwa 65.000 Quadratmetern\""}, {"kategorie": "", "text": "Er liegt im 1. und 3. Bezirk ([[Innere]] Stadt bzw. [[Landstraße]]), entlang des [[Wienflusses]], und erstreckt sich vom [[Parkring]] (1. Bezirk, [[Innere]] Stadt) bis zum [[Heumarkt]] (3. Bezirk, [[Landstraße]])"}, {"kategorie": "", "text": "Der Stadtpark wurde 1862 eröffnet und ist das erste öffentliche Parkprojekt Wiens, das nach der Schleifung der Stadtmauern und der damit verbundenen Stadterweiterung angelegt wurde. Der Park wurde vom Landschaftsarchitekten Josef Selleny entworfen und unter der Leitung des Gartenarchitekten Rudolf Siebeck realisiert. Der Park wurde im Stil eines englischen Landschaftsgartens angelegt, was ihm eine naturnahe, romantische Atmosphäre verleiht"}, {"kategorie": "", "text": "Das bekannteste Denkmal im Stadtpark ist das vergoldete Denkmal des Wiener Walzerkönigs Johann Strauss (Sohn). Es ist eines der meistfotografierten Denkmäler Wiens und ein Wahrzeichen des Parks"}, {"kategorie": "", "text": "Ein weiteres bedeutendes Denkmal ist das zu Ehren des Komponisten Franz Schubert errichtete Denkmal. Der Stadtpark beherbergt auch Denkmäler und Büsten weiterer berühmter Persönlichkeiten, darunter der Komponisten Franz Lehár und Robert Stolz, sowie der Maler Hans Makart und Emil Jakob Schindler."}]'::jsonb, ''),
  ('parkring', 'Parkring', '', '', '', '', 'Parkring', '[{"kategorie": "allg.", "text": "\"Teil der berühmten [[Wiener]] Ringstraße, die als repräsentativer Boulevard die historische Altstadt umgibt\""}, {"kategorie": "", "text": "Der Parkring verläuft im 1. Wiener Gemeindebezirk ([[Innere]] Stadt) entlang des [[Stadtparks]] und ist für seine prächtigen Gebäude, Hotels und historischen Bauten bekannt"}, {"kategorie": "", "text": "Der Parkring ist von imposanten Gebäuden im Stil des [[Historismus]] und der [[Gründerzeit]] geprägt, die im 19. Jahrhundert erbaut wurden. Diese Gebäude spiegeln die architektonische Pracht und das kulturelle Erbe Wiens wider"}]'::jsonb, ''),
  ('majolikahaus', 'Majolikahaus', '', '', '', '', 'Majolika-Haus', '[{"kategorie": "hist.", "text": "\"berühmtes Wohnhaus, das zwischen 1898 und 1899 von dem österreichischen Architekten Otto Wagner entworfen wurde\""}, {"kategorie": "", "text": "Es befindet sich an der [[Linken]] Wienzeile 40 im 6. Wiener Gemeindebezirk ([[Mariahilf]]) und ist ein herausragendes Beispiel für den [[Wiener]] Jugendstil, auch als [[Sezessionsstil]] bekannt"}, {"kategorie": "", "text": "Der Name \"Majolika-Haus\" leitet sich von den bunten Majolikafliesen ab, die die Fassade des Gebäudes bedecken. Diese Fliesen, die aus glasiertem Steingut bestehen, sind mit floralen Mustern verziert und verleihen dem Gebäude eine leuchtende, farbenfrohe Erscheinung. Die Fassade ist in den Farben Blau, Grün, Rot und Gelb gehalten und stellt eine stilisierte Blumenranke dar, die typisch für den Jugendstil ist."}]'::jsonb, ''),
  ('wiinzaeunhaus', 'Wiinzäunhaus', '', '', '', '', 'Wienzeilenhaus', '[{"kategorie": "hist.", "text": "\"bedeutendes Bauwerk des Wiener Jugendstils, das von dem berühmten Architekten Otto Wagner entworfen wurde\" (auch bekannt als [[Wienzeilengebäude]])"}, {"kategorie": "", "text": "Es befindet sich an der [[Linken]] Wienzeile 38 im 6. Wiener Gemeindebezirk ([[Mariahilf]]), in unmittelbarer Nachbarschaft zum [[Majolika-Haus]] und dem [[Haus mit goldener Kuppel]] (auch bekannt als [[Medienhaus]] oder [[Köhlerhaus]])"}, {"kategorie": "", "text": "Das Wienzeilenhaus wurde zwischen 1898 und 1899 erbaut und gilt als eines der Hauptwerke des Jugendstils in Wien. Es zeichnet sich durch eine elegante, klar strukturierte Fassade aus, die durch dekorative Elemente des Jugendstils ergänzt wird. Ein besonderes Merkmal des Gebäudes ist die Verwendung von polychromen (mehrfarbigen) Fliesen und der Verzicht auf historisierende Stilelemente, was typisch für Wagners moderne Architekturauffassung war"}, {"kategorie": "", "text": "Die Fassade ist mit Blattornamenten und goldfarbenen Details verziert, die dem Gebäude einen charakteristischen Glanz verleihen. Insbesondere das prächtige Gitterwerk und die floralen Motive sind bemerkenswerte Beispiele für die kunstvolle Gestaltung im Jugendstil."}]'::jsonb, ''),
  ('wiinzaeungebaeude', 'Wiinzäungebäude', '', '', '', '', 'Wienzeilengebäude', '[{"kategorie": "hist.", "text": "\"bedeutendes Bauwerk des Wiener Jugendstils, das von dem berühmten Architekten Otto Wagner entworfen wurde\" (auch bekannt als [[Wienzeilenhaus]])"}, {"kategorie": "", "text": "Es befindet sich an der [[Linken]] Wienzeile 38 im 6. Wiener Gemeindebezirk ([[Mariahilf]]), in unmittelbarer Nachbarschaft zum [[Majolika-Haus]] und dem [[Haus mit goldener Kuppel]] (auch bekannt als [[Medienhaus]] oder [[Köhlerhaus]])"}, {"kategorie": "", "text": "Das Wienzeilenhaus wurde zwischen 1898 und 1899 erbaut und gilt als eines der Hauptwerke des Jugendstils in Wien. Es zeichnet sich durch eine elegante, klar strukturierte Fassade aus, die durch dekorative Elemente des Jugendstils ergänzt wird. Ein besonderes Merkmal des Gebäudes ist die Verwendung von polychromen (mehrfarbigen) Fliesen und der Verzicht auf historisierende Stilelemente, was typisch für Wagners moderne Architekturauffassung war"}, {"kategorie": "", "text": "Die Fassade ist mit Blattornamenten und goldfarbenen Details verziert, die dem Gebäude einen charakteristischen Glanz verleihen. Insbesondere das prächtige Gitterwerk und die floralen Motive sind bemerkenswerte Beispiele für die kunstvolle Gestaltung im Jugendstil."}]'::jsonb, ''),
  ('sezessionsstil', 'Sezessionsstil', '', '', '', '', 'Secessionsstil', '[{"kategorie": "hist.", "text": "\"Kunst- und Architekturbewegung, die sich um die Wende vom 19. zum 20. Jahrhundert in Wien entwickelte\" (Synonym für [[Wiener Jugendstil]])"}, {"kategorie": "", "text": "Diese Bewegung ist Teil des größeren Jugendstil-Stils, der in verschiedenen europäischen Ländern als Art Nouveau (Frankreich und Belgien) oder Modern Style (England) bekannt ist"}, {"kategorie": "", "text": "Der Sezessionsstil zeichnet sich durch eine Kombination aus innovativem Design, künstlerischer Ausdruckskraft und einer Abkehr von traditionellen, historistischen Stilrichtungen aus"}]'::jsonb, 'Wiina Jugendsdüü'),
  ('urania', 'Urania', '', '', '', '', 'Urania', '[{"kategorie": "hist.", "text": "\"Wiener Urania\" (bedeutendes öffentliches Gebäude in Wien, das als Bildungs- und Kulturzentrum dient und ein markantes Beispiel für die Architektur der Wiener Moderne ist)"}, {"kategorie": "", "text": "Sie befindet sich im 1. Wiener Gemeindebezirk (Innere Stadt), an der Mündung des [[Wienflusses]] in den [[Donaukanal]], und ist heute Volksbildungshaus samt Sternwarte, Kino und Café"}, {"kategorie": "", "text": "Das im Jugendstil errichtete Gebäude  wurde 1910 eröffnet und beinhaltet eines der ältesten Planetarien der Welt, die im Kuppelbau untergebracht ist"}]'::jsonb, ''),
  ('donau', 'Donau', '', '', '', '', 'Donau', '[{"kategorie": "hist.", "text": "\"größter Fluss Österreichs\""}, {"kategorie": "", "text": "Er durchfließt Wien und teilt die Stadt in zwei Teile: den linksseitigen Teil (westlich der Donau) und den rechtsseitigen Teil (östlich der Donau)"}, {"kategorie": "", "text": "In Wien zweigt von der Donau der [[Donaukanal]] ab, der durch das Stadtzentrum fließt und wichtige Bereiche wie den 1. Bezirk ([[Innere]] Stadt) versorgt."}]'::jsonb, ''),
  ('donautuam', 'Donautuam', '', '', '', '', 'Donauturm', '[{"kategorie": "hist.", "text": "\"markantes Wahrzeichen und höchster freistehender Turm in Österreich\" (252m hoch)"}, {"kategorie": "", "text": "Er befindet sich im [[Donaupark]] im 22. Wiener Gemeindebezirk ([[Donaustadt]]) und bietet von seinem Aussichtsplateau samt Drehrestaurant eine beeindruckende Aussicht auf die Stadt Wien und die Donau"}, {"kategorie": "", "text": "Der Donauturm wurde zwischen 1962 und 1964 anlässlich der Wiener Internationalen Gartenschau (WIG 64) erbaut, die im Donaupark stattfand. Der Entwurf stammt von dem österreichischen Architekten Hannes Lintl"}, {"kategorie": "", "text": "Der Donauturm ist 252 Meter hoch, was ihn zu einem der höchsten Bauwerke in Österreich macht. Der Turmschaft besteht aus Stahlbeton, und auf der Höhe von 150 bis 170 Metern befinden sich zwei Aussichtsplattformen."}]'::jsonb, ''),
  ('donaupark', 'Donaupark', '', '', '', '', 'Donaupark', '[{"kategorie": "allg.", "text": "weitläufiger öffentlicher Park im 22. Bezirk Wiens ([[Donaustadt]]), der sich entlang der [[Neuen]] Donau und nahe der [[Donauinsel]] erstreckt"}, {"kategorie": "", "text": "Der Donaupark wurde in den frühen 1960er Jahren auf einem Gelände angelegt, das zuvor als Mülldeponie und Schießplatz genutzt wurde. Die Umgestaltung in einen Park war Teil der Vorbereitungen für die Wiener Internationale Gartenschau 1964 (WIG 64), die ein großes internationales Ereignis war. Nach dem Ende der Gartenschau blieb der Park als dauerhafte Grünfläche erhalten und entwickelte sich zu einem beliebten Erholungsgebiet"}, {"kategorie": "", "text": "Der Donaupark umfasst eine Fläche von etwa 604.000 Quadratmetern. Er ist großzügig angelegt und bietet eine Vielzahl von Landschaftselementen, darunter weitläufige Wiesen, Blumenbeete, Teiche und Baumgruppen."}]'::jsonb, ''),
  ('donauinsl', 'Donauinsl', '', '', '', '', 'Donauinsel', '[{"kategorie": "allg.", "text": "künstlich angelegte Insel in Wien, die sich über eine Länge von etwa 21 Kilometern zwischen der [[Donau]] und der [[Neuen]] Donau erstreckt"}, {"kategorie": "", "text": "Sie liegt im 21. und 22. Bezirk Wiens ([[Floridsdorf]] bzw. [[Donaustadt]]) und ist ein bedeutendes Naherholungsgebiet sowie ein wichtiger Teil des Hochwasserschutzsystems der Stadt"}, {"kategorie": "", "text": "Berühmtheit erlangte die Donauinsel vor allem auch durch das alljährlich stattfindende [[Donauinselfest]])"}]'::jsonb, ''),
  ('donauinslfest', 'Donauinslfest', '', '', '', '', 'Donauinselfest', '[{"kategorie": "wörtlich", "text": "\"eine der bedeutendsten Freiluftereignisse im Wiener Veranstaltungskalender mit mehreren Bühnen, zahlreichen nationalen wie internationalen Musikgenres, kulturellen Aktivitäten und kulinarischen Angeboten\""}, {"kategorie": "", "text": "Das Donauinselfest zieht alljährlich an jeweils einem Wochenende im Juni Millionen von Besuchern an, der Eintritt ist frei"}, {"kategorie": "", "text": "Legendär und unvergessen ist Falcos Donauinselkonzert vom 26. Juni 1993, eines seiner letzten Konzerte"}]'::jsonb, ''),
  ('heirich', 'heirich', '', '', '', '', 'heurig', '[{"kategorie": "wörtlich", "text": "diesjährig"}, {"kategorie": "", "text": "noch nicht einjährig"}, {"kategorie": "fig.", "text": "unerfahren, noch grün hinter den Ohren"}]'::jsonb, ''),
  ('prooda', 'Prooda', '', '', '', '', 'Prater', '[{"kategorie": "allg.", "text": "\"Der Wiener Prater\" (vom lateinischen \"pratum\"=\"Wiesengrund\")"}, {"kategorie": "", "text": "öffentliche Parkanlage und Naherholungsgebiet samt Vergnügungspark ([[Wurstelprater]]), erstreckt sich über eine Fläche von mehr als 6 Millionen Quadratmeter im 2. Wiener Gemeindebezirk ([[Leopoldstadt]])"}, {"kategorie": "", "text": "Der Begriff „Prater“ bezieht sich in der Regel auf zwei Hauptbereiche: den [[Wurstelprater]], einen historischen Vergnügungspark, und den [[Grünen]] Prater, eine weitläufige Grünfläche, die als einer der wichtigsten Naherholungsgebiete der Stadt dient"}, {"kategorie": "", "text": "Ursprünglich ein Jagdgebiet für die [[Habsburger]] wurden die [[Praterauen]] erstmals 1766 für die Öffentlichkeit freigegeben. Markantestes Wahrzeichen des Wiener Wurstelpraters ist das [[Riesenrad]]."}]'::jsonb, ''),
  ('proodapark', 'Proodapark', '', '', '', '', 'Praterpark', '[{"kategorie": "allg.", "text": "\"Der Wiener Praterpark\" (vom lateinischen \"pratum\"=\"Wiesengrund\")"}, {"kategorie": "", "text": "öffentliche Parkanlage und Naherholungsgebiet samt Vergnügungspark ([[Wurstelprater]]), erstreckt sich über eine Fläche von mehr als 6 Millionen Quadratmeter im 2. Wiener Gemeindebezirk ([[Leopoldstadt]])"}, {"kategorie": "", "text": "Der Begriff „Prater“ bezieht sich in der Regel auf zwei Hauptbereiche: den [[Wurstelprater]], einen historischen Vergnügungspark, und den [[Grünen]] Prater, eine weitläufige Grünfläche, die als einer der wichtigsten Naherholungsgebiete der Stadt dient"}, {"kategorie": "", "text": "Ursprünglich ein Jagdgebiet für die [[Habsburger]] wurden die [[Praterauen]] erstmals 1766 für die Öffentlichkeit freigegeben. Markantestes Wahrzeichen des Wiener Wurstelpraters ist das [[Riesenrad]]."}]'::jsonb, ''),
  ('jesuitnwiisn', 'Jesuitnwiisn', '', '', '', '', 'Jesuitenwiese', '[{"kategorie": "allg.", "text": "große Freifläche im [[Grünen]] Prater, dem weitläufigen Park- und Erholungsgebiet im 2. Wiener Gemeindebezirk ([[Leopoldstadt]])"}, {"kategorie": "", "text": "Sie ist eine der bekanntesten und am häufigsten genutzten Wiesen im Prater und dient als beliebter Ort für Freizeitaktivitäten, Sport und Veranstaltungen"}, {"kategorie": "", "text": "Die Jesuitenwiese erhielt ihren Namen von den Jesuiten, einem katholischen Orden, der das Gelände in der Vergangenheit für landwirtschaftliche Zwecke nutzte"}]'::jsonb, ''),
  ('kriiau', 'Kriiau', '', '', '', '', 'Krieau', '[{"kategorie": "allg.", "text": "Trabrennbahn Krieau"}, {"kategorie": "", "text": "jener Teil der Wiener Praterauen im 2. Wiener Gemeindebezirk ([[Leopoldstadt]]), in welchem sich Wiens älteste Trabrennbahn (\"die Trabrennbahn Krieau\") befindet (eröffnet 1878)."}]'::jsonb, ''),
  ('lusthaus', 'Lusthaus', '', '', '', '', 'Lusthaus', '[{"kategorie": "allg.", "text": "historisches Gebäude am südlichen Ende der [[Prater]] Hauptallee im 2. Wiener Gemeindebezirk ([[Leopoldstadt]]), nahe der [[Galopprennbahn]] Freudenau"}, {"kategorie": "", "text": "Es diente ursprünglich als kaiserliches Jagd- und Ausflugspavillon, ist ein bedeutendes architektonisches und kulturelles Denkmal sowie ein symbolträchtiger Ort im [[Grünen]] Prater und steht - seit der Verlegung des [[Donaukanals]] - nicht mehr direkt am Wasser"}, {"kategorie": "", "text": "Früher war das Lusthaus ein beliebter Treffpunkt von Adel und Bürgertum, heute berbergt es ein Café-Restaurant an einem der idyllischsten Plätze Wiens."}]'::jsonb, ''),
